window.MONSTER_CHUNK_44 = [{"name":"Large Magma Elemental","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["earth","elemental","extraplanar","fire"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":8,"ac_flat_footed":16,"ac_mods":"-1 Dex, +8 natural, -1 size","hp":60,"hd":"8d10+16","hdvalue":8,"fort":8,"ref":5,"will":2,"dr":"5/-","immunities":["fire","elemental traits"],"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20}],"speed_mod":"earth glide","melee":"2 slams +11 (1d8+4 plus burn)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"burn","details":"1d6, DC 14"},{"type":"lava puddle"}],"strength":18,"dexterity":8,"constitution":15,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":8,"cmb":13,"cmd":22,"feats":[{"feat":"Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":15},{"skill":"Knowledge (dungeoneering)","value":9},{"skill":"Perception","value":11},{"skill":"Stealth","value":6}],"languages":["Ignan"],"sq":[{"type":"earth glide"}],"environments":["any (Plane of Fire)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This rocky monster glows with an internal heat. Red light spills from its eyes and mouth, as well as fractures in its outer surface.","group":"Elemental","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Burn","kind":"Ex","details":"A magma elemental's burn DC includes a -2 racial penalty, as their fires don't burn quite as hot as true elemental flames."},{"type":"Earth Glide","kind":"Ex","details":"A burrowing magma elemental can pass through stone, dirt, lava, or almost any other sort of earth except metal as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple, though the area it passes through feels warm for 1 round afterward and often retains a strangely smooth texture, as if the stone had been polished. A move earth spell cast on an area containing a burrowing magma elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Lava Puddle","kind":"Su","details":"Once per day as a full-round action, a magma elemental can vomit forth a puddle of lava that fills its space to a depth of 2-3 inches and counts as difficult terrain. Any creature that moves through this puddle of lava takes 2d6 points of fire damage. This damage continues for 1d3 rounds after the creature leaves the lava pool, although then it only inflicts 1d6 points of fire damage per round. The lava puddle solidifies and is safe to touch after a number of rounds equal to the elemental's Hit Dice. At the GM's discretion, this puddle of lava could start secondary fires."}],"description":"In the border areas between the Plane of Earth and Plane of Fire, volcanoes and continent-sized lava flows are commonplace. Elementals in this area tend to have aspects of both planes, and the typical sort is the magma elemental, an earth elemental with a core of liquid fire. Magma elementals generally have a somewhat feral or bestial appearance.","ecology":"","habitat_society":""},{"name":"Large Mud Elemental","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["earth","elemental","extraplanar","water"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"30 ft."}],"ac":17,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+1 Dex, +7 natural, -1 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":9,"ref":7,"will":2,"dr":"5/-","immunities":["acid","elemental traits"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":10},{"type":"swim","speed":30}],"speed_mod":"earth glide","melee":"2 slams +12 (1d8+5 plus entrap)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"entrap","details":"DC 17, 10 minutes, hardness 5, hp 10"}],"strength":20,"dexterity":12,"constitution":17,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":8,"cmb":14,"cmd":25,"feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush","type":"bonus"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":12},{"skill":"Escape Artist","value":8},{"skill":"Knowledge (planes)","value":4},{"skill":"Perception","value":11},{"skill":"Stealth","value":4},{"skill":"Swim","value":13}],"languages":["Terran"],"environments":["any land (Plane of Earth)","any water (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This animate pile of mud seems barely able to maintain the semblance of a humanoid form made of dripping sludge.","group":"Elemental","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Earth Glide","kind":"Ex","details":"A burrowing mud elemental can pass through dirt, gravel, or other loose or porous solid matter as easily as a fish swims through water. It cannot use this ability to pass through a solid barrier such as a stone or brick wall. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. A move earth spell cast on an area containing a burrowing mud elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Entrap","kind":"Ex","details":"The mud from an elemental's entrap ability can be washed away in 1d3 rounds of immersion in water."}],"description":"Where the Plane of Earth borders the Plane of Water, a mixing of the fundamental elements occurs-it is in this borderland that the mud elementals dwell. Scorned by earth and water elementals, mud elementals usually look like vaguely recognizable blobs of mud in the shape of a Material Plane creature, whether a humanoid, an animal, or even an immense insect. The exact density of their muddy bodies varies-some might be composed of silty water, while others are thick, like river clay. Large and powerful mud elementals tend to have worm-like, reptilian, or frog-like forms.","ecology":"","habitat_society":""},{"name":"Large Water Elemental","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["elemental","extraplanar","water"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +1 dodge, +6 natural, -1 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":9,"ref":8,"will":2,"dr":"5/-","immunities":["elemental traits"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":90}],"melee":"2 slams +12 (1d8+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"drench"},{"type":"vortex","details":"DC 19"},{"type":"water mastery"}],"strength":20,"dexterity":14,"constitution":17,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":8,"cmb":14,"cmd":27,"feats":[{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Great Cleave"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Escape Artist","value":11},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":9},{"skill":"Stealth","value":5},{"skill":"Swim","value":24}],"languages":["Aquan"],"environments":["any (Plane of Water)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This translucent creature's shape shifts between a spinning column of water and a crashing wave.","group":"Elemental","source":"PFRPG Bestiary","special_abilities":[{"type":"Drench","kind":"Ex","details":"The elemental's touch puts out nonmagical flames of Large size or smaller. The creature can dispel magical fire it touches as dispel magic (caster level equals elemental's HD)."},{"type":"Vortex","kind":"Su","details":"A water elemental can create a whirlpool as a standard action, at will. This ability functions identically to the whirlwind special attack, but can only form underwater and cannot leave the water."},{"type":"Water Mastery","kind":"Ex","details":"A water elemental gains a +1 bonus on attack and damage rolls if both it and its opponent are touching water. If the opponent or the elemental is touching the ground, the elemental takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the elemental is initiating or resisting these kinds of attacks."}],"description":"Water elementals are patient, relentless creatures made of living fresh or salt water. They prefer to hide or drag their opponents into the water to gain an advantage. As with other elementals, all water elementals have their own unique shapes and appearances. Most appear as wave-like creatures with vaguely humanoid faces and smaller wave \"arms\" to either side. Another common form is that of any aquatic creature, such as a shark or octopus, but made entirely out of water. Elemental Height Weight Vortex Save DC Vortex Height Small 4 ft. 34 lbs. 13 10-20 ft. Medium 8 ft. 280 lbs. 15 10-30 ft. Large 16 ft. 2,250 lbs. 19 10-40 ft. Huge 32 ft. 18,000 lbs. 22 10-50 ft. Greater 36 ft. 21,000 lbs. 25 10-60 ft. Elder 40 ft. 24,000 lbs. 28 10-60 ft.","ecology":"","habitat_society":""},{"name":"Leucrotta","cr":5,"xp":1600,"alignment":"CE","size":"Large","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":57,"hd":"6d10+24","hdvalue":6,"fort":9,"ref":6,"will":4,"immunities":["disease","poison"],"speed":[{"type":"land","speed":60},{"type":"climb","speed":30}],"melee":"bite +10 (2d6+7/19-20), 2 hooves +5 (1d6+2)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"lure"},{"type":"powerful bite"}],"strength":21,"dexterity":12,"constitution":18,"intelligence":11,"wisdom":14,"charisma":17,"baseatk":6,"cmb":12,"cmd":23,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Bluff)"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Bluff","value":12},{"skill":"Climb","value":13},{"skill":"Stealth","value":9}],"languages":["Common"],"sq":[{"type":"sound mimicry","details":"voices"}],"environments":["temperate forests","temperate hills","tropical forests","tropical hills"],"organizations":["solitary","pair","pack (3-12)"],"treasure":"standard","description_visual":"This freakish beast has the head of a badger, the hooves of a stag, and a wide mouth with sharp ridges of bone instead of teeth.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Lure","kind":"Su","details":"At any point that a leucrotta's targets are unaware of it (for example, if the leucrotta is hiding or concealed in darkness), the leucrotta can call out to the targets, who must be in line of sight and within 60 ft. When the leucrotta calls out, the targets must make a DC 16 Will save or fall under the effects of a suggestion to approach the sound of the leucrotta's voice. This effect functions identically to a mass suggestion spell with a caster level equal to the leucrotta's Hit Dice. A creature that saves cannot be affected again by the same leucrotta's lure for 24 hours. The lure is a language-dependant effect, and if the leucrotta uses the victim's name during the lure, the victim takes a -4 penalty on its saving throw. This is a sonic mind-affecting charm effect. The save DC is Charisma-based."},{"type":"Powerful Bite","kind":"Ex","details":"A leucrotta's bite attack always applies 1-1/2 times its Strength modifier on damage rolls and threatens a critical hit on a roll of 19-20. When a leucrotta bites an object, its bite treats the object as having a hardness of 5 less than the object's actual hardness rating."}],"description":"Reputed to be descended from hyenas and a demon lord, these creatures are intelligent and cruel, using their astounding vocal mimicry to lure foolish and unsuspecting creatures to where the pack can torment them at its leisure before finally devouring them. Five ft. tall at the shoulder, its tawny fur often coated with dried and clotted filth, the leucrotta is a powerful beast weighing over 800 pounds. The sharp bone ridges that line its oversized jaws instead of teeth are incredibly durable and, combined with massive jaw muscles, allow its bite to shear through bone and even steel. Leucrottas consume their prey gear and all; they vomit up what they cannot digest and pick through the debris in search of valuable items that might help them lure in prey. Leucrottas sometimes lead packs of gnolls, or even of their bestial cousins the crocottas. They refuse to let themselves be used as beasts of burden, but sometimes allow favored gnoll companions to ride them into battle as steeds. The leucrotta in a gnoll pack generally thinks of itself as the leader of that group, and treats any established gnoll chieftain poorly in an attempt to goad that gnoll into attacking it. Those leucrottas that succeed in slaying a gnoll leader typically find it much easier to assume the role of tribal leader. Crocotta These degenerate offshoots of leucrottas have animal level intelligence, but sense a kinship with leucrottas and obey them instinctively. Treat a crocotta as an advanced dire hyena with Improved Critical (bite) as a bonus feat. A crocotta looks similar to a leucrotta, save that it has shorter back legs, giving it a hunched, more hyena-like appearance. Leucrottas view crocottas with disdain and even shame, but it's not unusual to find these large hyena-like beasts in close proximity to a leucrotta pack. Crocottas are popular attractions in traveling carnivals, where unscrupulous con artists bill them as cursed humanoids or animals.","ecology":"","habitat_society":""},{"name":"Lizard Scion","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"humanoid","subtypes":["reptilian"],"init":0,"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+8 natural, -1 size","hp":45,"hd":"7d8+14","hdvalue":7,"fort":7,"ref":2,"will":3,"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"mwk trident +9 (2d6+3), bite +5 (1d8+1) or 2 claws +7 (1d6+3), bite +5 (1d8+1)","ranged":"mwk javelin +5 (1d8+3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"blood rage"}],"strength":16,"dexterity":11,"constitution":14,"intelligence":9,"wisdom":12,"charisma":11,"baseatk":5,"cmb":9,"cmd":19,"feats":[{"feat":"Cleave"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (trident)"}],"skills":[{"skill":"Perception","value":5},{"skill":"Swim","value":14}],"languages":["Draconic"],"sq":[{"type":"hold breath"},{"type":"lizardfolk blood"}],"environments":["temperate swamps"],"organizations":["solitary","band (with 3-12 lizardfolk)","tribe (with 13-60 lizardfolk)"],"description_visual":"This muscular lizardfolk towers above others of its kind, a primeval behemoth painted with elaborate designs.","source":"Monster Codex","special_abilities":[{"type":"Lizardfolk Blood","kind":"Ex","details":"A lizard scion counts as a lizardfolk for all effects related to race."}],"description":"Every few generations, a lizard scion is born to a lizardfolk tribe. With twice the life span of a typical lizardfolk and a large and muscular stature, a scion typically rises to become the leader of her tribe. Lizardfolk show great- often unquestioning-devotion to scions, believing they are blessings from the spirits and divine in nature. In many ways, tribes see them as living monuments to the lost greatness of their people, singing songs of an era when every lizardfolk was as large and impressive as the scion.\n\nA lizard scion isn't officially recognized until her 100th birthday, though many might suspect that she is one. At that point, the tribe holds a ceremony in which they present the newly titled lizard scion with a special war trident as a mark of status. These ancient tridents are never used by ordinary lizardfolk, and most have been handed down through their tribe for generations, sometimes sitting untouched for hundreds of years until the naming of a new lizard scion.\n\nSome lizard scions become great protectors and voices of wisdom among their people, leading a tribe to previously unknown accomplishments and stability within its hidden enclave. Others attempt to build alliances with other lizardfolk tribes or even unite two tribes into one. A tribe of lizardfolk being systematically pushed out of its ancestral territory, however, might see the coming of a lizard scion as a sign that war is imminent, and could be spurred to take up arms once and for all against the so-called \"civilized\" encroachers.\n\nThere are rumors that deep in some jungles or swamps there live entire tribes of dinosaur-herding lizard scions that have bred true as a race, but such stories may be little more than the overactive imaginations of explorers and treasure hunters.\n\nLizard scions average 10 ft. in height and 500 pounds, though this can vary by tribe and age. Unlike boggard priest-kings, lizard scions are never fat, but rather hugely muscled specimens with excellent reflexes.","ecology":"","habitat_society":"","gear":"mwk trident, 2 mwk javelins"},{"name":"Lurker In Light","cr":5,"xp":1600,"alignment":"NE","size":"Small","type":"fey","subtypes":["extraplanar"],"init":8,"senses":[{"type":"low-light vision"}],"ac":18,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+4 Dex, +3 natural, +1 size","hp":44,"hd":"8d6+16","hdvalue":8,"fort":4,"ref":10,"will":9,"defensive_abilities":["blend with light"],"dr":"5/cold iron","immunities":["blindness"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"average"}],"melee":"2 claws +9 (1d3+1) or  dagger +9 (1d3+1/19-20 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+3d6"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mage hand"}]},{"frequency":"3/day","spells":[{"spell":"blindness/deafness"},{"spell":"daylight"}]}],"strength":13,"dexterity":18,"constitution":15,"intelligence":14,"wisdom":16,"charisma":17,"baseatk":4,"cmb":4,"cmd":18,"feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Escape Artist","value":15},{"skill":"Fly","value":17},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":16},{"skill":"Stealth","value":19},{"skill":"Survival","value":11}],"languages":["Aklo","Common","Sylvan"],"sq":[{"type":"daylight door"},{"type":"poison use"},{"type":"ritual gate"}],"environments":["any land (extraplanar)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"standard (dagger)","description_visual":"This large-eyed humanoid looks like a glowing, emaciated elven child save for its small, transparent wings.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Blend With Light","kind":"Su","details":"In areas of bright light, lurkers are invisible. As with greater invisibility, they may attack and still remain invisible. In shadowy illumination, a lurker loses this invisibility, though like all creatures in shadows, they have concealment unless the viewer has darkvision. If the lurker is flying, its fluttering wings partially negate this effect, giving it only partial concealment (20%) rather than total concealment."},{"type":"Daylight Door","kind":"Sp","details":"Once per day, a lurker can use dimension door, transporting only itself and up to 50 pounds of material. The start and end points of the teleport must be in areas of bright light; if the destination lacks sufficient light, the teleport fails but doesn't expend the ability for the day."},{"type":"Poison","kind":"Ex","details":"Lurkers typically coat their daggers with shadow essence poison. Shadow essence poison: Injury; save Fortitude DC 17; frequency 1/round for 6 rounds; initial effect 1 Str drain; secondary effect 1d3 Str damage; cure 1 save."},{"type":"Ritual Gate","kind":"Su","details":"By sacrificing one or more humanoid victims, a lurker or group of lurkers can create a gate to the Material Plane, one of the Elemental Planes, or the realm of the fey, either to return home or to conjure allies. Creating a gate for travel requires the sacrifice of five victims-the gate created remains open for 1 minute. Creating a gate to bring allies to the Material Plane requires one sacrifice for every HD of the creature intended to pass through the gate (so five sacrifices can bring a lurker or a Medium air elemental, eight can bring a Large earth elemental, and so on). The sacrifices don't need to be simultaneous; as long all sacrifices occur at some point during the hour-long ritual, the magic continues to build until it reaches the required total."}],"description":"Malicious and alien fey, lurkers in light venture to the Material Plane to perpetrate strangely targeted mischief, stealing and killing according to a logic or system of justice only they understand. Gnomes in particular seem to incur these unexplained attacks, leading some to believe that lurkers may be agents of ancient and vengeful forces. Creatures of the light, lurkers are visible only in dim illumination, with anything brighter than a flickering torch making them completely invisible, even as they savage their enemies-a prospect terrifying to those civilized races that equate light with safety.\n\nA lurker in light turns conventional wisdom on its head, for they detest darkness and the creatures that dwell in it, yet they themselves are sadistic and evil. They particularly hate darkmantles, dwarves, and creatures from the Plane of Shadow, and given the time, they enjoy torturing such creatures to death if they can capture them alive.\n\nIf killed, a lurker in light disintegrates over the course of several minutes into 2d6 pounds of dust that radiates faint evocation magic and glows for 1d6 days with a cold light equal to that provided by a candle. This dust damages shadows as if it were holy water, with a pound of dust equal to one flask of holy water.\n\nA lurker in light is 3 ft. tall, but weighs only 20 pounds.","ecology":"","habitat_society":""},{"name":"Manticore","cr":5,"xp":1600,"alignment":"LE","size":"Large","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+2 Dex, +6 natural, -1 size","hp":57,"hd":"6d10+24","hdvalue":6,"fort":9,"ref":7,"will":3,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"clumsy"}],"melee":"bite +10 (1d8+5), 2 claws +10 (2d4+5)","ranged":"4 spikes +8 (1d6+5)","space":"10 ft.","reach":"5 ft.","strength":20,"dexterity":15,"constitution":18,"intelligence":7,"wisdom":12,"charisma":9,"baseatk":6,"cmb":12,"cmd":24,"cmd_special":"+4 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Weapon Focus (spikes)"}],"skills":[{"skill":"Fly","value":-3},{"skill":"Perception","value":9},{"skill":"Survival","value":4,"special":"+8 tracking"}],"languages":["Common"],"environments":["warm hills","warm marshes"],"organizations":["solitary","pair","pride (3-6)"],"treasure":"standard","description_visual":"This creature has a vaguely humanoid head, the body of a lion, and the wings of a dragon. Its tail ends in long, sharp spikes.","source":"PFRPG Bestiary","special_abilities":[{"type":"Spikes","kind":"Ex","details":"With a snap of its tail, a manticore can loose a volley of four spikes as a standard action (make an attack roll for each spike). This attack has a range of 180 ft. with no range increment. All targets must be within 30 ft. of each other. The creature can launch only 24 spikes in any 24-hour period."}],"description":"Manticores are fierce predators that patrol a wide area in search of fresh meat. A typical manticore is about 10 ft. long and weighs about 1,000 pounds. Some have more human-like heads, usually with beards. Males and females look much alike. Manticores eat any meat, even carrion, though they prefer human flesh and rarely pass up an opportunity for such a delicacy. They are smart and social enough to bargain with or bully evil humanoids into alliances or offering tribute, and more powerful creatures may hire or bribe them to guard or patrol a place or area. They like lairs in high places, such as hilltops and caves in cliffs. Although manticores were likely a magical creation, they have long since established themselves as a naturally occurring species. Curiously, manticores seem strangely fecund, and can interbreed with a number of other similarly shaped creatures, including lions, dire lions, lamias, sphinxes, and even chimeras. The progeny of a manticore and an unusual mate is summarized on the table below. Manticore's Mate Offspring Lion Standard manticore Dire lion Advanced manticore Lamia Lamia with spiked tail and spikes special attack Sphinx Sphinx with spiked tail and spikes special attack Chimera Chimera with spiked tail and spikes special attack.","ecology":"","habitat_society":""},{"name":"Megatherium","cr":5,"xp":1600,"alignment":"N","size":"Huge","type":"animal","init":0,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":18,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"+10 natural, -2 size","hp":59,"hd":"7d8+28","hdvalue":7,"fort":9,"ref":5,"will":3,"speed":[{"type":"land","speed":30},{"type":"climb","speed":10}],"melee":"2 claws +10 (1d8+7 plus trip)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d8+10"}],"strength":25,"dexterity":10,"constitution":19,"intelligence":2,"wisdom":13,"charisma":6,"baseatk":5,"cmb":14,"cmd":24,"cmd_special":"+4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":14}],"environments":["temperate forests","warm forests"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"The great sloth, standing on its hind legs, can reach the treetops with its agile tongue to grab at foliage.","group":"Megafauna","source":"PFRPG Bestiary 2","description":"The megatherium is a massive sloth weighing 10,000 pounds. It can balance on its hind legs and tail, allowing it to reach up to 20 ft. high.","ecology":"","habitat_society":""},{"name":"Mercane","cr":5,"xp":1600,"alignment":"LN","size":"Large","type":"outsider","subtypes":["extraplanar"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 dodge, +4 natural, -1 size","hp":51,"hd":"6d10+18","hdvalue":6,"fort":8,"ref":4,"will":8,"sr":20,"speed":[{"type":"land","speed":30}],"melee":"mwk Large  falchion +8  (2d6+3/18-20)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"plane shift"}]},{"frequency":"3/day","spells":[{"spell":"dimension door"},{"spell":"invisibility","details":"self only"}]}],"strength":15,"dexterity":14,"constitution":16,"intelligence":20,"wisdom":17,"charisma":15,"baseatk":6,"cmb":9,"cmd":22,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Expertise"},{"feat":"Dodge"}],"skills":[{"skill":"Appraise","value":14},{"skill":"Bluff","value":11},{"skill":"Diplomacy","value":8},{"skill":"Intimidate","value":8},{"skill":"Knowledge (arcana)","value":14},{"skill":"Knowledge (planes)","value":14},{"skill":"Perception","value":12},{"skill":"Profession (merchant)","value":9},{"skill":"Sense Motive","value":12},{"skill":"Sleight of Hand","value":11},{"skill":"Spellcraft","value":14}],"languages":["Abyssal","Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"sq":[{"type":"secret chest"}],"environments":["any land","any underground"],"organizations":["solitary","company (1-4 and 3-12 bodyguards of various races)"],"treasure":"double (masterwork Large falchion)","description_visual":"The tall, blue-skinned humanoid is clad in loose, flowing robes. Its alien face has too many eyes and its hands have too few fingers.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Secret Chest","kind":"Sp","details":"A mercane can retrieve or hide an extradimensional storage chest, as the secret chest spell (caster level 5th). The mercane doesn't need an expensive replica chest to use this ability; any chest will do. It can only use this ability on one chest at a time."}],"description":"Mysterious merchants of all things magical, mercanes are relatively weak and noncombative for creatures of their size. They prefer to bargain and haggle rather than to fight, but because they wander the planes seeking and trading magical goods, they typically travel with an entourage of hired bodyguards. Mercanes are capable of defending themselves, and often carry masterwork Large falchions. Yet these weapons are primarily for show, as mercanes prefer to let their bodyguards deal with violent opponents. If a situation turns ugly, mercanes typically use their magical abilities to flee, abandoning their hirelings if necessary.\n\nMercanes are known throughout the planes as traders in magical items. Each has a secret chest filled with wares stashed away, ready to be pulled out when it's time to haggle and close a deal (or to bribe a potential obstacle). Mercanes are therefore not easily robbed, and they only surrender the contents of a secret chest when they have no other choice. Mercanes have no interest in mundane goods, no matter how fine or rare.\n\nOnly magical objects earn their attention and their coin.\n\nThey're known for driving hard, but fair, bargains, and for hiring adventurers from time to time to recover certain goods of interest for a fair price. Although they are not particularly brave, they hold contracts sacrosanct and keep their agreements.\n\nRumors and legends abound as to the origins of the mercanes and their reasons for seeking out and buying magical items. Their home plane is unknown, and they have wandered between the worlds for as long as any can recall.\n\nStories claim the mercanes feed on the magic items they acquire, or even need them in order to reproduce.\n\nThere are also tales of a war in a far corner of the planes, with the mercanes serving the roles of arms merchants, aggressors, or defenders, depending on who tells the story.\n\nMercanes are 10 ft. tall and weigh 500 pounds.","ecology":"","habitat_society":""},{"name":"Mirror Man","cr":5,"xp":1600,"alignment":"NE","size":"Medium","type":"construct","init":6,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":17,"ac_flat_footed":11,"ac_mods":"+6 Dex, +1 dodge, +1 natural","hp":53,"hd":"6d10+20","hdvalue":6,"hp_mods":["fast healing 2"],"fort":2,"ref":8,"will":4,"dr":"5/bludgeoning","immunities":["blindness","gaze attacks","illusions of the pattern subschool","construct traits"],"weaknesses":["susceptible to mind-affecting effects"],"speed":[{"type":"land","speed":30}],"melee":"+1 longsword +10 (1d8+4/19-20)","ranged":"dagger +12 (1d4+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect magic"},{"spell":"light"}]}],"strength":16,"dexterity":23,"intelligence":15,"wisdom":15,"charisma":12,"baseatk":6,"cmb":9,"cmd":26,"feats":[{"feat":"Alertness"},{"feat":"Dodge"},{"feat":"Quick Draw"}],"skills":[{"skill":"Knowledge (local)","value":8},{"skill":"Knowledge (nobility)","value":8},{"skill":"Linguistics","value":7},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":10},{"skill":"Survival","value":5}],"languages":["Common (can't speak)","Giant (can't speak)","Hallit (can't speak)","Skald (can't speak)","telepathy 100 ft."],"sq":[{"type":"alert master"},{"type":"mirror sight"},{"type":"scrying focus"},{"type":"soul mirror"}],"environments":["any land"],"organizations":["solitary","pair","cell (3-7)"],"treasure":"standard (+1 longsword, daggers [4])","description_visual":"Tall and lean, this hooded figure resembles a human until the terrible face beneath the cowl is revealed-nothing but a featureless mirror, reflecting a hard, cold world.","source":"AP 68","special_abilities":[{"type":"Alert Master","kind":"Su","details":"Three times per day, a mirror man can send a brief message to a creature it is familiar with (typically its master). This effect is similar to the sending spell, but it takes only a standard action, the communication is one way, and the target cannot respond to the sending."},{"type":"Mirror Sight","kind":"Ex","details":"A mirror man has no eyes, but is capable of visually perceiving through the use of blindsight, darkvision, and low-light vision."},{"type":"Scrying Focus","kind":"Su","details":"Mirror men are specifically created to interact with the spell Irriseni mirror sight in special ways. The construct's mirrored face can serve as a known mirror, allowing the caster to see from the perspective of the construct's face with normal sight. The caster may also communicate telepathically with the mirror man. As a swift action, the mirror man can choose to remember and record up to 1 minute of what it sees. This memory is visual only and can be viewed remotely through Irriseni mirror sight or played back across its face. The mirror man can only retain 1 minute of images; when its memory is full, old memories are erased so it can remember new ones. The caster may interact with the mirror man's soul mirror even after the construct body is destroyed as long as the face itself remains unbroken. If the construct has not been destroyed, an opponent must succeed at a sunder attempt targeting the mirrored face to break the mirror. The mirrored face is considered a separate weapon with a hardness of 1 and hit points equal to the mirror man's Hit Dice. If the construct has been destroyed, the mirrored face can be smashed as a standard action."},{"type":"Soul Mirror","kind":"Su","details":"The soul of a mirror man is bound within its mirrored face. As long as the face remains intact, it can be affixed to a new construct body using the same cost to create a new construct. Once a soul is bound to a mirror, the soul continues to learn, and if the mirror is later affixed to a new body, the soul retains any memories from its previous bodies."},{"type":"Susceptible to Mind-Affecting Effects","kind":"Ex","details":"The self-aware and autonomous nature of a mirror man makes it susceptible to mind-affecting effects, despite the fact that it is a construct."}],"description":"At a glance, mirror men are easily mistaken for humans. They are tall, slender, and graceful and mask their true selves in fine hooded cloaks appropriate to Irrisen's eternal winter. Nevertheless, their grace is the product of precision, not elegance, and their hooded garments serve to obscure an inhuman countenance. A mirror man has no eyes, nose, or mouth. Its face is a featureless mirror, affixed atop a lifeless body. Behind this mirror is a vacant hole left behind when the body was prepared for its current use.\n\nEcology\n\nMirror men are constructs whose origin is less than a century old, and are typically found in larger Irriseni cities such as Whitethrone and Algidheart. Just as guardian dolls are animated with the souls of children, mirror men get their spark from adults-usually criminals. They are created to be the spies and assassins of the White Witches, and their construct nature makes them utterly loyal to the Jadwiga. Mirror men are cunning, merciless, and determined in the execution of their orders. Underneath their garments they resemble zombies, or even flesh golems. All unnecessary internal organs and fluids have been removed, and what remains is wrapped in cold muscle and skin of a grayish hue that is magically maintained and self-repairing. No eyes remain within their skulls, but the soul trapped within the mirror can sense all movement nearby.\n\nWhile some golems and constructs are simple replacements for guards and protectors, the mirror men of Irrisen represent a very specific design. They are intended to investigate, spy, and report, and are created with abilities carefully selected to help them fulfill these purposes. Even their ability to magically create light serves to allow the witches to see better while peering through their looking-glass faces. Mirror men are trained to be familiar with nobility of the region, to detect forgeries, and to investigate crimes. There remains a flaw in their creation, however- any caster of Irriseni mirror sight can peer through the face of any mirror man she's familiar with. The White Witches of Irrisen often assume foreigners don't know their secrets, but nothing save tradition prevents an outlander from learning the spell. A mirror man can't attempt to resist an unwanted connection, and its only recourse when used as an ambulatory sensor for someone unauthorized is to cover its face and send a warning to the witch who governs it.\n\nHabitat & Society\n\nFor centuries, the Iron Guard observed and recorded events in Whitethrone; its members nominally served the Jadwiga but their true allegiance was to Baba Yaga-a fact that did not go unnoticed by the descendants of the 14 queens. Under Elvanna's reign, the mirror men were created to act as the eyes and ears, not of the Iron Guard, but of the White Witches themselves. For decades, the Jadwiga Elvanna maintained that the role of the mirror men was to provide additional oversight of the kingdom, but with the recent usurpation of Baba Yaga, the mirror men's role as the White Witches' secret police has become evident. Mirror men have broad authority to question, search, and arrest anyone but the Jadwiga themselves. Even with telepathy, mirror men avoid self-expression as much as possible whenever a gesture or pointed finger will suffice. In Whitethrone, it is universally understood when a mirror man jabs a finger at someone, followed by a tap on the open palm of their other hand, it means the citizen should stand still and allow himself to be viewed through the unsettling visage of the mirror man.\n\nThere is no love lost between the mirror men and any of Irrisen's monstrous citizens (or the Iron Guard, for that matter). The constructs' presence only fuels an atmosphere of paranoia and distrust as the monsters are left wondering who might be watching them as well as the native Ulfen slaves.\n\nConstruction\n\nThe creation of a mirror man requires a single living creature (usually human), which is killed during the process. Its manufacture requires costly alchemical reagents and a mirror faceplate crafted specifically for the creature. The creature's soul is bound to the mirror, which prevents it from continuing to the afterlife and protects it from being resurrected or raised from the dead. Most of the original creature's memories are expunged, but mirror men retain many of their originals skills; consequently, the most effective mirror men are former career criminals and foreign spies. The creation process is excruciating to the victim, and creating a mirror man constitutes an evil act.\n\nMirror Man\n\nCL 11th; Price 24,500 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, animate dead, cat's grace, geas/quest, Irriseni mirror sight, magic jar, sending, creator must be caster level 11th, soul of a living creature that dies or is slain during the creation process; Skill Craft (sculpture) DC 17 or Heal DC 17; Cost 12,500 gp","ecology":"Mirror men are constructs whose origin is less than a century old, and are typically found in larger Irriseni cities such as Whitethrone and Algidheart. Just as guardian dolls are animated with the souls of children, mirror men get their spark from adults-usually criminals. They are created to be the spies and assassins of the White Witches, and their construct nature makes them utterly loyal to the Jadwiga. Mirror men are cunning, merciless, and determined in the execution of their orders. Underneath their garments they resemble zombies, or even flesh golems. All unnecessary internal organs and fluids have been removed, and what remains is wrapped in cold muscle and skin of a grayish hue that is magically maintained and self-repairing. No eyes remain within their skulls, but the soul trapped within the mirror can sense all movement nearby.\n\nWhile some golems and constructs are simple replacements for guards and protectors, the mirror men of Irrisen represent a very specific design. They are intended to investigate, spy, and report, and are created with abilities carefully selected to help them fulfill these purposes. Even their ability to magically create light serves to allow the witches to see better while peering through their looking-glass faces. Mirror men are trained to be familiar with nobility of the region, to detect forgeries, and to investigate crimes. There remains a flaw in their creation, however- any caster of Irriseni mirror sight can peer through the face of any mirror man she's familiar with. The White Witches of Irrisen often assume foreigners don't know their secrets, but nothing save tradition prevents an outlander from learning the spell. A mirror man can't attempt to resist an unwanted connection, and its only recourse when used as an ambulatory sensor for someone unauthorized is to cover its face and send a warning to the witch who governs it.","habitat_society":"For centuries, the Iron Guard observed and recorded events in Whitethrone; its members nominally served the Jadwiga but their true allegiance was to Baba Yaga-a fact that did not go unnoticed by the descendants of the 14 queens. Under Elvanna's reign, the mirror men were created to act as the eyes and ears, not of the Iron Guard, but of the White Witches themselves. For decades, the Jadwiga Elvanna maintained that the role of the mirror men was to provide additional oversight of the kingdom, but with the recent usurpation of Baba Yaga, the mirror men's role as the White Witches' secret police has become evident. Mirror men have broad authority to question, search, and arrest anyone but the Jadwiga themselves. Even with telepathy, mirror men avoid self-expression as much as possible whenever a gesture or pointed finger will suffice. In Whitethrone, it is universally understood when a mirror man jabs a finger at someone, followed by a tap on the open palm of their other hand, it means the citizen should stand still and allow himself to be viewed through the unsettling visage of the mirror man.\n\nThere is no love lost between the mirror men and any of Irrisen's monstrous citizens (or the Iron Guard, for that matter). The constructs' presence only fuels an atmosphere of paranoia and distrust as the monsters are left wondering who might be watching them as well as the native Ulfen slaves.\n\nConstruction\n\nThe creation of a mirror man requires a single living creature (usually human), which is killed during the process. Its manufacture requires costly alchemical reagents and a mirror faceplate crafted specifically for the creature. The creature's soul is bound to the mirror, which prevents it from continuing to the afterlife and protects it from being resurrected or raised from the dead. Most of the original creature's memories are expunged, but mirror men retain many of their originals skills; consequently, the most effective mirror men are former career criminals and foreign spies. The creation process is excruciating to the victim, and creating a mirror man constitutes an evil act.\n\nMirror Man\n\nCL 11th; Price 24,500 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, animate dead, cat's grace, geas/quest, Irriseni mirror sight, magic jar, sending, creator must be caster level 11th, soul of a living creature that dies or is slain during the creation process; Skill Craft (sculpture) DC 17 or Heal DC 17; Cost 12,500 gp"},{"name":"Mist Drake","cr":5,"xp":1600,"alignment":"NE","size":"Large","type":"dragon","subtypes":["air"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"fogvision"},{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +1 dodge, +7 natural, -1 size","hp":57,"hd":"6d12+18","hdvalue":6,"fort":8,"ref":7,"will":6,"immunities":["paralysis","sleep"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":80,"maneuverability":"average"}],"melee":"bite +9 (2d6+4), tail slap +4 (1d8+2)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"fogburst"}],"strength":19,"dexterity":15,"constitution":16,"intelligence":9,"wisdom":12,"charisma":10,"baseatk":6,"cmb":11,"cmd":24,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Hover"}],"skills":[{"skill":"Fly","value":9},{"skill":"Intimidate","value":9},{"skill":"Perception","value":10},{"skill":"Stealth","value":7,"special":"+15 in fog or mist"},{"skill":"Survival","value":10}],"languages":["Draconic"],"sq":[{"type":"misty camouflage"},{"type":"speed surge"}],"environments":["cold coasts","any hills","any marshes","temperate coasts"],"organizations":["solitary","pair","rampage (3-12)"],"treasure":"standard","description_visual":"This lanky dragon's dappled grayish scales and sprawling wings shift and fade in color, blending in with the mist.","group":"Drake","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Fogburst","kind":"Su","details":"As a standard action, a mist drake can expel a ball of solid mist that explodes into a cloud of fog upon impact. This attack has a range of 60 ft. and deals 3d6 points of bludgeoning damage to all creatures in a 20-foot radius (Reflex DC 16 half). A flying creatures that fails its Reflex save is pushed 1d4 x 5 ft. from the center of the fogburst's area of effect (taking 1d6 points of damage per 10 ft. if it strikes a solid object), while creatures on the ground are knocked prone on a failed save. The area of effect of the fogburst is filled with mist (as obscuring mist) for 1d4 rounds after impact. Once a mist drake has used its fogburst attack, it cannot do so again for 1d6 rounds. The save DC is Constitution-based."},{"type":"Fogvision","kind":"Ex","details":"A mist drake can see normally through any form of natural or magical mist, fog, or precipitation."},{"type":"Misty Camouflage","kind":"Ex","details":"A mist drake can use Stealth to hide whenever it is in or adjacent to an area of mist, even while being observed."},{"type":"Speed Surge","kind":"Ex","details":"Three times per day as a swift action, a mist drake can draw on its draconic heritage for a boost of strength and speed that enables it to take an additional move action in that round."}],"description":"Mist drakes are less openly aggressive than most drakes, as they are not as physically strong and imposing as most of their kin. Their bodies are narrow and serpentine, more suited for quick strikes and hit-and-run tactics than for close combat. However, they excel at stealth for creatures of their size, and can expel a burst of thick fog whenever they need to create a diversion or screen themselves from archers trying to target them. In the mist, they move swiftly and silently to disperse groups of foes with their explosive breath and then single out one of their enemies for a quick and deadly attack before their victim's allies can regroup and come to its rescue. Mist drakes mate only once few decades, but are more caring parents than others of their ilk. After the clutch of two to six eggs hatch, the hatchlings stay with their mother for up to 20 years before seeking out their own hunting territory. Mist drakes live up to 200 years. A typical mist drake is 13 ft. long from head to tail tip, but these lithe dragons rarely weigh more than 1,000 pounds.","ecology":"","habitat_society":""},{"name":"Mummy","cr":5,"xp":1600,"alignment":"LE","size":"Medium","type":"undead","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["despair (30 ft., paralyzed for 1d4 rounds, Will DC 16 negates)"],"ac":20,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+10 natural","hp":60,"hd":"8d8+24","hdvalue":8,"fort":4,"ref":2,"will":8,"dr":"5/-","immunities":["undead traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20}],"melee":"slam +14 (1d8+10 plus mummy rot)","space":"5 ft.","reach":"5 ft.","strength":24,"dexterity":10,"intelligence":6,"wisdom":15,"charisma":15,"baseatk":6,"cmb":13,"cmd":23,"feats":[{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":16},{"skill":"Stealth","value":11}],"languages":["Common"],"environments":["any"],"organizations":["solitary","warden squad (2-6)","guardian detail (7-12)"],"treasure":"standard","description_visual":"Wrapped from head to toe in ancient strips of moldering linen, this humanoid moves with a shuffling gait.","source":"PFRPG Bestiary","special_abilities":[{"type":"Despair","kind":"Su","details":"All creatures within a 30-foot radius that see a mummy must make a DC 16 Will save or be paralyzed by fear for 1d4 rounds. Whether or not the save is successful, that creature cannot be affected again by the same mummy's despair ability for 24 hours. This is a paralysis and a mind-affecting fear affect. The save DC is Charisma-based."},{"type":"Mummy Rot","kind":"Su","details":"Curse and disease-slam; save Fort DC 16; onset 1 minute; frequency 1/day; effect 1d6 Con and 1d6 Cha; cure -. Mummy rot is both a curse and disease and can only be cured if the curse is first removed, at which point the disease can be magically removed. Even after the curse element of mummy rot is lifted, a creature suffering from it cannot recover naturally over time. Anyone casting a conjuration (healing) spell on the afflicted creature must succeed on a DC 20 caster level check, or the spell is wasted and the healing has no effect. Anyone who dies from mummy rot turns to dust and cannot be raised without a resurrection or greater magic. The save DC is Charisma-based."}],"description":"Created to guard the tombs of the honored dead, mummies are ever vigilant for those who would desecrate their sacred ground. Mummies are created through a rather lengthy and gruesome embalming process, during which all of the body's major organs are removed and replaced with dried herbs and flowers. After this process, the flesh is anointed with sacred oils and wrapped in purified linens. The creator then finishes the ritual with a create undead spell. Although most mummies are created merely as guardians and remain loyal to their charge until their destruction, certain powerful mummies have much more free will. The majority are at least 10th-level clerics, and are often kings or pharaohs who have called upon dark gods or sinister necromancers to bind their souls to their bodies after death-usually as a means to extend their rule beyond the grave, but at times simply to escape what they fear will be an eternity of torment in their own afterlife.","ecology":"","habitat_society":""},{"name":"Mythic Gargoyle","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"monstrous humanoid","subtypes":["earth","mythic"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":62,"hd":"5d10+35","hdvalue":5,"fort":4,"ref":6,"will":6,"dr":"10/epic and magic","speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"bite +8 (1d4+3), 2 claws +8 (1d6+3), gore +8 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"60-ft. line, 6d6 acid damage, Reflex DC 15 half, usable every 1d4 rounds"},{"type":"mythic power","details":"2/day, surge +1d6"}],"strength":17,"dexterity":14,"constitution":16,"intelligence":6,"wisdom":11,"charisma":7,"baseatk":5,"cmb":8,"cmd":20,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will","type":"mythic"},{"feat":"Skill Focus (Fly)"}],"skills":[{"skill":"Fly","value":12},{"skill":"Perception","value":5},{"skill":"Stealth","value":11,"special":"+17 +6 in stony environs"}],"languages":["Common","Terran"],"sq":[{"type":"freeze"},{"type":"opportunistic movement"},{"type":"possess statue"}],"environments":["any"],"organizations":["solitary","pair","wing (3-12)"],"treasure":"standard","description_visual":"This living stone statue takes the shape of a horned and winged humanoid, and green acid drips from its mouth.","group":"Gargoyle","source":"Mythic Adventures","special_abilities":[{"type":"Freeze","kind":"Ex","details":"A gargoyle can hold itself so still it appears to be a statue. A gargoyle that uses freeze can take 20 on its Stealth check to hide in plain sight as a stone statue."},{"type":"Opportunistic Movement","kind":"Ex","details":"A mythic gargoyle can rapidly move to take advantage of an opponent's weakened defenses. When an opponent within 30 ft. takes an action that provokes an attack of opportunity, as an immediate action the mythic gargoyle can expend one use of mythic power to move up to 40 ft., ending its movement next to the creature that provoked the attack of opportunity and making an attack of opportunity against that creature. The gargoyle's movement from this ability doesn't provoke attacks of opportunity."},{"type":"Possess Statue","kind":"Su","details":"A mythic gargoyle can expend one use of mythic power to possess and animate a Medium stone statue within 100 ft. The possessed statue functions as a non-mythic gargoyle and lasts as long as the statue is in range and the gargoyle concentrates. When using this ability, the gargoyle's actual body is immobile (as if using its freeze ability) and helpless. It can stop using this ability as a move action. If the statue is destroyed, the gargoyle's life force returns to its own body."}],"description":"A mythic gargoyle is a king or queen among its kind, usually gaining its power from an earth deity, a mythic gem embedded in its chest, or centuries of exposure to powerful magic. It has a distinct appearance, and other members of its wing slowly shift to match its look.\n\nMythic Kapoacinth\n\nAn aquatic mythic gargoyle is nearly identical to a mythic gargoyle, but usually has an electricity breath weapon instead of acid. Some have the ability to possess coral or wood statues instead of stone.","ecology":"","habitat_society":""},{"name":"Mythic Griffon","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"magical beast","subtypes":["mythic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+2 Dex, +8 natural, -1 size","hp":62,"hd":"5d10+35","hdvalue":5,"fort":7,"ref":6,"will":4,"dr":"5/epic","speed":[{"type":"land","speed":30},{"type":"fly","speed":100,"maneuverability":"average"}],"melee":"bite +8 (1d6+4 plus grab), 2 talons +10 (1d6+4)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"mythic power","details":"2/day, surge +1d6"},{"type":"pounce"},{"type":"power dive"},{"type":"rake","details":"2 claws +8, 1d4+4"}],"strength":18,"dexterity":15,"constitution":16,"intelligence":5,"wisdom":13,"charisma":8,"baseatk":5,"cmb":10,"cmb_special":"+4 vs. grapple","cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Flyby Attack","type":"bonus"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (talons)","type":"mythic"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Fly","value":6},{"skill":"Perception","value":12}],"languages":["Common (cannot speak)"],"environments":["temperate hills"],"organizations":["solitary","pair","pride (6-10)"],"treasure":"incidental","description_visual":"This majestic beast combines the features of a sleek black eagle and the strong, lean musculature of a panther.","group":"Griffon","source":"Mythic Adventures","special_abilities":[{"type":"Power Dive","kind":"Ex","details":"A flying mythic griffon can move up to four times its speed when it charges. If its charge begins 40 or more ft. above its target, its first attack deals double damage. It must be flying downward at an angle of 45 degrees or steeper to use this ability."}],"description":"A mythic griffon is a superior specimen-perhaps augmented by magic, blessed by a nature goddess, or the descendant of an exceptional line of mighty griffons dating back to the first of its kind. Stronger and faster than other griffons, it is aware of its superiority (even though it is no more intelligent than a non-mythic griffon) and will only consent to a truly heroic rider who respects it as an equal rather than as a mere steed.\n\nIf approached by a suitable rider, a mythic griffon is no more difficult to train than a non-mythic griffon. The eggs of a mythic griffon usually sell for twice as much as those of a common griffon, though there is no way to tell if a particular hatchling is mythic until it is several weeks or months old. Mythic griffons are extremely protective of their mates, eggs, and offspring, and may spend the rest of their lives in the search for vengeance against thieves or murderers- even working with lesser beings as allies or riders.\n\nA mythic griffon who cannot find a suitable griffon mate may consort with unicorns, awakened horses, or mythic horses or unicorns. The offspring of such unions is usually a hippogriff, but in rare cases is a mythic hippogriff. Because of prejudice against a hippogriff's animal-level intelligence, a mythic griffon usually leaves its offspring once they are grown.\n\nA mythic griffon can carry up to 400 pounds as a light load, 800 pounds as a medium load, and 1,200 pounds as a heavy load.","ecology":"","habitat_society":""},{"name":"Mythic Owlbear","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"magical beast","subtypes":["mythic"],"init":7,"init_special":"mythic","senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+1 Dex, +7 natural, -1 size","hp":67,"hd":"5d10+40","hdvalue":5,"fort":10,"ref":5,"will":2,"dr":"5/epic","sr":16,"speed":[{"type":"land","speed":30}],"melee":"bite +9 (1d8+5), 2 claws +9 (1d6+5 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"disorienting pounce"},{"type":"mythic power","details":"2/day, surge +1d6"},{"type":"pounce"},{"type":"rend","details":"2 claws, 1d6+7"}],"strength":21,"dexterity":12,"constitution":18,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":5,"cmb":11,"cmb_special":"+4 vs. grapple","cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":12}],"environments":["temperate forests"],"organizations":["solitary","pair","pack (3-8)"],"treasure":"incidental","description_visual":"This beast has the general size and shape of a great bear, yet the head and feathers of an owl.","group":"Owlbear","source":"Mythic Adventures","special_abilities":[{"type":"Disorienting Pounce","kind":"Ex","details":"A creature that a mythic owlbear hits when using its pounce ability is automatically staggered for 1 round."}],"description":"A mythic owlbear may have been created by a mythic mage, or adopted as the favored pet of a mythic druid. Though as short-tempered and bloodthirsty as other owlbears, a mythic owlbear has the sense to avoid or flee foes more powerful than itself.","ecology":"","habitat_society":""},{"name":"Night Scale Assassins","cr":5,"xp":1600,"race":"half-elf","classes":[{"class":"rogue","level":5},{"class":"assassin","level":1}],"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["elf","human"],"init":3,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+4 armor, +3 Dex, +0 natural","hp":34,"hd":"6d8+6","hdvalue":6,"fort":2,"ref":7,"will":1,"save_mods":"+2 vs. enchantments","defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"short sword +4 (1d6+1/19-20) or   dagger +4 (1d4+1/19-20)","ranged":"+1 hand crossbow +8 (1d4+1/19-20) or dagger +6 (1d4+2/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death attack","details":"DC 13"},{"type":"sneak attack","details":"+4d6"}],"strength":13,"dexterity":16,"constitution":12,"intelligence":14,"wisdom":10,"charisma":10,"baseatk":3,"cmb":4,"cmd":17,"feats":[{"feat":"Point-Blank Shot"},{"feat":"Rapid Reload (hand crossbow)"},{"feat":"Skill Focus (Stealth)","type":"bonus"},{"feat":"Weapon Focus (hand crossbow)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":9},{"skill":"Climb","value":10},{"skill":"Disable Device","value":12},{"skill":"Disguise","value":9},{"skill":"Escape Artist","value":12},{"skill":"Intimidate","value":8},{"skill":"Perception","value":11},{"skill":"Sleight of Hand","value":12},{"skill":"Stealth","value":15}],"languages":["Common","Elven","Shoanti","Varisian"],"sq":[{"type":"elf blood"},{"type":"poison use"},{"type":"rogue talents","details":"bleeding attack +3, lasting poison"},{"type":"trapfinding","details":"+2"}],"environments":["any urban (Magnimar)"],"organizations":["solitary"],"treasure":"none","description_visual":"This lithe half-elven woman wields a hand crossbow and is bedecked in dark leather that blends in with the shadows.","group":"Magnimar","source":"Magnimar City Of Monuments","description":"Magnimar has its share of criminal elements, but the Night Scales claim to rule the city's cutthroat underworld. Their various operations and misdeeds include smuggling, extortion, theft, and even outright murder every now and then. Members of the Night Scales range from toughs to pickpockets to con artists, following a strict hierarchy of power based on skill as much as social connections. Among these ranks, the Night Scale assassins are perhaps the most feared members of the thieves' guild. Such assassins are responsible for taking care of nosy adventurers or pesky guards who don't know to mind their own business. Night Scale assassins work to silence some of Magnimar's mouthiest nobles as well as its uncorrupted political figures, and it is rumored that if one can get a hold of the shadowy gang, private parties might be able to arrange an assassination for a steep price.\n\nA Night Scale assassin puts much care and time into surveying her targets. She tails them over the course of a week, noting where they go to market, what time they wake up, and whom they talk to on a regular basis. This wealth of information allows the assassin to choose the perfect time and place for an unsuspecting hit.","ecology":"","habitat_society":"","gear":"+1 studded leather, +1 hand crossbow, daggers (5), short sword, potion of cure moderate wounds, potions of invisibility [2], shadow essence"},{"name":"Nightmare","cr":5,"xp":1600,"alignment":"NE","size":"Large","type":"outsider","subtypes":["evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+2 Dex, +8 natural, -1 size","hp":51,"hd":"6d10+18","hdvalue":6,"fort":8,"ref":7,"will":3,"speed":[{"type":"land","speed":40},{"type":"fly","speed":90,"maneuverability":"good"}],"melee":"bite +9 (1d4+4), 2 hooves +4 (1d6+2 plus 1d4 fire)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"smoke"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"plane shift","details":"self plus 1 rider only"}]}],"strength":18,"dexterity":15,"constitution":16,"intelligence":13,"wisdom":13,"charisma":12,"baseatk":6,"cmb":11,"cmd":23,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Run"}],"skills":[{"skill":"Fly","value":13},{"skill":"Intimidate","value":10},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":7},{"skill":"Survival","value":10}],"languages":["Abyssal","Infernal"],"environments":["any (Abaddon)"],"organizations":["solitary"],"treasure":"none","description_visual":"This eerie horse-like creature's skin is an inky blackness. Fire spurts from its hair and nostrils, and its hooves spray sparks.","source":"PFRPG Bestiary","special_abilities":[{"type":"Smoke","kind":"Su","details":"In battle, a nightmare exhales smoke that chokes and blinds foes, filling a 15-foot cone each round as a free action. Anyone in the cone must succeed on a DC 16 Fortitude save or become sickened until 1d6 minutes after leaving the area. This smoke acts as obscuring mist for the purposes of concealment. The smoke persists for 1 round. The save DC is Constitution-based."}],"description":"Nightmares are flaming harbingers of death. They allow only the most evil of creatures to ride them, and are never mere mounts, but rather willing partners in destruction.","ecology":"","habitat_society":""},{"name":"Nothosaur","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"animal","init":1,"senses":[{"type":"low-light vision"}],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":57,"hd":"6d8+30","hdvalue":6,"fort":9,"ref":6,"will":4,"speed":[{"type":"land","speed":20},{"type":"swim","speed":40}],"melee":"bite +10 (1d8+6), tail slap +7 (1d8+3)","space":"10 ft.","reach":"10 ft.","strength":23,"dexterity":12,"constitution":18,"intelligence":2,"wisdom":15,"charisma":7,"baseatk":4,"cmb":11,"cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Multiattack"},{"feat":"Toughness"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":11},{"skill":"Swim","value":14}],"sq":[{"type":"sprint"}],"environments":["any water"],"organizations":["solitary","pair","herd (3-12)"],"treasure":"none","description_visual":"This long-necked reptile swims through the water propelled by four paddle-like ft., whipping a long and slender tail behind it as it gnashes its sharp, needle-like teeth.","source":"AP 60","special_abilities":[{"type":"Sprint","kind":"Ex","details":"Once per minute, a nothosaur may sprint, increasing its land speed to 40 ft. for 1 round."}],"description":"The nothosaur resembles a smaller version of the land-based brachiosaurus, sharing the distinctive long neck and tail and short legs of its herbivorous brethren. Nothosaurs are also similar in many ways to seals-they spend much of their time in the water, including when they hunt, but emerge to sleep and breed on land. They lay their eggs in massive sandy mounds in the summer, then abandon their nests and slip back into the sea. A nothosaur is most vulnerable out of the water, but when caught unawares, it can return to the water with alarming speed, notwithstanding its awkwardly short legs and disproportionately large neck and tail. Nothosaurs can exist in water of any temperature, but prefer the warmer equatorial waters. Herds of nothosaurs make seasonal migrations, following schools of fish over the course of many months. From head to the tip of its tail, an adult nothosaur is 12 ft. long and weighs 3,000 pounds.","ecology":"","habitat_society":""},{"name":"Ochre Jelly","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"ooze","init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":4,"ac_touch":4,"ac_flat_footed":4,"ac_mods":"-5 Dex, -1 size","hp":63,"hd":"6d8+36","hdvalue":6,"fort":8,"ref":-3,"will":-3,"defensive_abilities":["split"],"immunities":["electricity","mind-affecting effects","ooze traits","slashing and piercing damage"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10}],"melee":"slam +5 (2d4+3 plus 1d4 acid and grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"2d4+3 plus 1d4 acid"}],"strength":14,"dexterity":1,"constitution":22,"wisdom":1,"charisma":1,"baseatk":4,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":12,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":10}],"environments":["temperate marshes","temperate underground"],"organizations":["solitary"],"treasure":"none","description_visual":"This yellow-orange amoeboid creature slithers across the ground, pseudopods grasping ahead of its slow approach.","source":"PFRPG Bestiary","special_abilities":[{"type":"Acid","kind":"Ex","details":"An ochre jelly secretes a digestive acid that dissolves only flesh (not bone) when it strikes a foe-creatures not made of flesh (including most constructs and oozes, skeletal undead, plants, and incorporeal creatures) are immune to the ochre jelly's acid damage."},{"type":"Split","kind":"Ex","details":"Slashing weapons, piercing weapons, and electricity attacks deal no damage to an ochre jelly. Instead the creature splits into two identical jellies, each with half of the original creature's current hit point total, rounded down. A jelly with 10 hit points or less cannot be further split and dies if reduced to 0 hit points."}],"description":"Ochre jellies are animate masses of protoplasm hued a sickly combination of yellow, orange, and brown. At rest, their flat, pulsing bodies stand roughly 6 inches tall and can stretch out to a wide diameter- in motion, they often ball up into quivering spherical shapes and almost seem to roll as they move. Their malleable bodies allow them to seep through cracks and holes far smaller than the space they fill.\n\nCreatures dwelling below ground often attempt to seal up any such cracks to fortify their lairs against ochre jellies.\n\nAn ochre jelly's highly specialized acid only dissolves flesh. This discovery has led many poisoners and hack alchemists to search out specimens for their tinkering.\n\nSome specialized weapons have resulted from these experiments that target the living body in wicked ways.\n\nRumors of a slow-release poison that breaks down the cellular walls in living creatures surfaced a few years ago, but its creator guards the secret with his life.\n\nNotes in a long-forgotten tome mention a burial practice used in faraway places that resembles cremation.\n\nInstead of burning the corpse to ashes, the practitioners seal the body into a stone sarcophagus with an ochre jelly so it can dissolve the body. Afterward, the morticians place the ochre jelly into a large canopic jar, complete with a bronze plaque naming the deceased. This practice protects items entombed with the body (which is quickly reduced to nothing but a polished skeleton), and the creature's essence, it is believed, still rides along with the living jelly.\n\nOchre jellies stand about 6 inches tall, spread out to a little over 10 ft. in diameter, and weigh upward of 2,600 pounds. When in combat, they tend to pile up upon themselves and exude long, dripping pseudopods to slam and grapple anything that moves.\n\nAlthough the typical ochre jelly has stats as presented here, in the deepest reaches of the underground world these mindless predators can grow to enormous sizes.\n\nPerhaps more disturbing, though, are rumors of ochre jellies that have developed additional methods of capturing prey. Adventurers speak of jellies capable of poisoning foes with a touch or exuding clouds of noxious gas that burns the eyes and throat, leaving those who draw too near helpless as the immense protoplasmic beast slithers over their bodies and begins to feed.","ecology":"","habitat_society":""},{"name":"Ogre Spider","cr":5,"xp":1600,"alignment":"N","size":"Huge","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":18,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+2 Dex, +8 natural, -2 size","hp":52,"hd":"7d8+21","hdvalue":7,"fort":8,"ref":4,"will":3,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"bite +8 (2d8+7 plus poison)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"web","details":"+5 ranged, DC 16, hp 7"}],"strength":21,"dexterity":15,"constitution":16,"wisdom":12,"charisma":2,"baseatk":5,"cmb":12,"cmd":24,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":29},{"skill":"Perception","value":5},{"skill":"Stealth","value":-2}],"sq":[{"type":"compression"}],"environments":["cold hills","cold underground","temperate hills","temperate underground"],"organizations":["solitary","pair"],"treasure":"incidental","description_visual":"This towering spider is the size of an elephant. Its legs have spiky joints and its face looks vaguely, but disturbingly, humanoid.","group":"Spider","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 18 (includes +2 racial bonus); frequency 1/round for 6 rounds; effect 1d4 Str and 1d4 Dex; cure 1 save."}],"description":"Ogre spiders are brutal, terrifying hunters that spin tangled webs capable of encasing entire trees. So-named because the arrangement of its eyes and mandibles gives it a face unnervingly similar to that of an ogre as much as for their size, ogre spiders can fit into nooks and tunnels far more narrow than one might expect.","ecology":"","habitat_society":""}];
